-- 00060_plays.sql
--
-- Plays (phase F1 of docs/plans/film-and-plays.md): the plays library on the
-- IQ tab, with animated court diagrams, and saving a play.
--
--   1. plays: library plays (owner_id null, written only by the server) and,
--      from F2, plays a coach draws (owner_id set). The full column set is
--      here so F2 does not need to change the table. For now signed-in players
--      read the library and an owner reads their own plays; nobody but the
--      server writes. F2 adds the editor (through a server route that checks
--      the diagram) and team playbook reads.
--   2. play_saves: a player saves a play, like drill_favorites (00042).
--   3. The 10 starter plays, generated from src/data/plays/library.ts.
--
-- diagram is checked in full by parseDiagram (src/lib/plays/diagram.ts); the
-- database only checks it is a version 1 object of a sensible size.
--
-- Safe to re-run.
--
-- NOTE ON STYLE: no apostrophes in the comments of this file, for the reason
-- given at the top of 00035. Keep it apostrophe-free.

-- =============================================================================
-- 1. PLAYS
-- =============================================================================
CREATE TABLE IF NOT EXISTS public.plays (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  -- null for a library play; a coach play goes with the coach account
  owner_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,
  title text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 80),
  slug text CHECK (slug IS NULL OR slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  -- the same lists as src/lib/plays/catalog.ts
  category text NOT NULL CHECK (category IN (
    'principles', 'half_court', 'pick_and_roll', 'blob', 'slob', 'press_break', 'zone_offence', 'end_of_quarter'
  )),
  min_age text NOT NULL CHECK (min_age IN ('U9', 'U10', 'U11', 'U12', 'U13', 'U14', 'U15', 'U16', 'U17', 'U18', 'Senior')),
  tags text[] NOT NULL DEFAULT '{}' CHECK (cardinality(tags) <= 10),
  description text NOT NULL DEFAULT '' CHECK (char_length(description) <= 600),
  coaching_points text[] NOT NULL DEFAULT '{}' CHECK (cardinality(coaching_points) <= 12),
  diagram jsonb NOT NULL CHECK (
    jsonb_typeof(diagram) = 'object' AND diagram ->> 'v' = '1' AND octet_length(diagram::text) <= 65536
  ),
  is_free boolean NOT NULL DEFAULT false,
  -- the library play a coach copied, kept if that play is later removed
  copied_from uuid REFERENCES public.plays(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  -- a library play is found by its slug
  CONSTRAINT plays_library_slug_check CHECK (owner_id IS NOT NULL OR slug IS NOT NULL)
);

-- Slugs are unique among library plays; coach plays have none
CREATE UNIQUE INDEX IF NOT EXISTS plays_library_slug_key ON public.plays (slug) WHERE owner_id IS NULL;
CREATE INDEX IF NOT EXISTS plays_owner_id_idx ON public.plays (owner_id) WHERE owner_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS plays_copied_from_idx ON public.plays (copied_from) WHERE copied_from IS NOT NULL;

ALTER TABLE public.plays ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Signed in players read library plays" ON public.plays;
CREATE POLICY "Signed in players read library plays" ON public.plays
  FOR SELECT TO authenticated USING (owner_id IS NULL);

DROP POLICY IF EXISTS "Owners read own plays" ON public.plays;
-- (select auth.uid()) is worked out once per query rather than once per row
CREATE POLICY "Owners read own plays" ON public.plays
  FOR SELECT TO authenticated USING ((select auth.uid()) = owner_id);

-- This project does not auto-grant new tables to the API roles (see 00008).
-- Read only for players: every write goes through the server for now.
GRANT SELECT ON public.plays TO authenticated;
GRANT ALL ON public.plays TO service_role;
REVOKE ALL ON public.plays FROM anon;

-- =============================================================================
-- 2. SAVED PLAYS
-- =============================================================================
CREATE TABLE IF NOT EXISTS public.play_saves (
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  play_id uuid NOT NULL REFERENCES public.plays(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, play_id)
);

-- The primary key leads with user_id, so deleting a play would otherwise scan
-- every save to find its rows
CREATE INDEX IF NOT EXISTS play_saves_play_id_idx ON public.play_saves (play_id);

ALTER TABLE public.play_saves ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users read own saved plays" ON public.play_saves;
CREATE POLICY "Users read own saved plays" ON public.play_saves
  FOR SELECT TO authenticated USING ((select auth.uid()) = user_id);

-- Only a play the player can read can be saved (the EXISTS runs under the
-- plays rules above), so a save cannot reveal that a private play exists
DROP POLICY IF EXISTS "Users save plays they can see" ON public.play_saves;
CREATE POLICY "Users save plays they can see" ON public.play_saves
  FOR INSERT TO authenticated WITH CHECK (
    (select auth.uid()) = user_id
    AND EXISTS (SELECT 1 FROM public.plays p WHERE p.id = play_id)
  );

DROP POLICY IF EXISTS "Users remove own saved plays" ON public.play_saves;
CREATE POLICY "Users remove own saved plays" ON public.play_saves
  FOR DELETE TO authenticated USING ((select auth.uid()) = user_id);

GRANT SELECT, INSERT, DELETE ON public.play_saves TO authenticated;
GRANT ALL ON public.play_saves TO service_role;
REVOKE ALL ON public.play_saves FROM anon;

-- =============================================================================
-- 3. LIBRARY PLAYS
-- =============================================================================
-- BEGIN LIBRARY PLAYS (generated from src/data/plays/library.ts by __tests__/plays-library.test.ts; do not edit by hand)
INSERT INTO public.plays (slug, title, category, min_age, tags, description, coaching_points, diagram, is_free) VALUES
  ('four-out-one-in', '4-out 1-in: pass and cut', 'principles', 'U10', ARRAY['motion', 'spacing', 'cutting']::text[], 'Four players outside the three-point line, one in the post. Every time you pass, you cut to the basket, and everyone fills the spot that just opened.', ARRAY['Pass, then cut hard to the basket. If you are open, you get it straight back.', 'Fill the spot that just opened, so there are always four out and one in.', 'Keep 12 to 15 feet from the nearest teammate, so one defender cannot guard two of you.', 'The post player (5) moves to the side the ball is on.', 'Catch, face the basket, then decide: shoot, drive or pass.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":15.5,"y":28.5},"o2":{"x":34.5,"y":28.5},"o3":{"x":5,"y":21},"o4":{"x":45,"y":21},"o5":{"x":34.5,"y":8}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":15.5,"y":28.5},"o2":{"x":34.5,"y":28.5},"o3":{"x":5,"y":21},"o4":{"x":45,"y":21},"o5":{"x":34.5,"y":8}},"ball":"o3","actions":[{"type":"pass","from":"o1","to":"o3","path":[]}]},{"ms":1000,"positions":{"o1":{"x":25,"y":7},"o2":{"x":15.5,"y":28.5},"o3":{"x":5,"y":21},"o4":{"x":34.5,"y":28.5},"o5":{"x":34.5,"y":8}},"ball":"o3","actions":[{"type":"cut","from":"o1","path":[]},{"type":"cut","from":"o2","path":[]},{"type":"cut","from":"o4","path":[]}],"note":"The passer cuts to the basket; the next player along fills their spot."},{"ms":1000,"positions":{"o1":{"x":45,"y":21},"o2":{"x":15.5,"y":28.5},"o3":{"x":5,"y":21},"o4":{"x":34.5,"y":28.5},"o5":{"x":15.5,"y":8}},"ball":"o3","actions":[{"type":"cut","from":"o1","path":[{"x":33,"y":13}]},{"type":"cut","from":"o5","path":[]}],"note":"Not open? Keep going out to the open spot. 5 follows the ball."},{"ms":1000,"positions":{"o1":{"x":45,"y":21},"o2":{"x":15.5,"y":28.5},"o3":{"x":5,"y":21},"o4":{"x":34.5,"y":28.5},"o5":{"x":15.5,"y":8}},"ball":"o2","actions":[{"type":"pass","from":"o3","to":"o2","path":[]}]},{"ms":1000,"positions":{"o1":{"x":45,"y":21},"o2":{"x":15.5,"y":28.5},"o3":{"x":5,"y":21},"o4":{"x":34.5,"y":28.5},"o5":{"x":15.5,"y":8}},"ball":"o4","actions":[{"type":"pass","from":"o2","to":"o4","path":[]}],"note":"Swing the ball to the other side."},{"ms":1000,"positions":{"o1":{"x":45,"y":21},"o2":{"x":25,"y":7},"o3":{"x":15.5,"y":28.5},"o4":{"x":34.5,"y":28.5},"o5":{"x":15.5,"y":8}},"ball":"o4","actions":[{"type":"cut","from":"o2","path":[]},{"type":"cut","from":"o3","path":[]}],"note":"Same again: pass, cut, fill."}]}'::jsonb, true),
  ('five-out-pass-cut-fill', '5-out: pass, cut, fill', 'principles', 'U9', ARRAY['motion', 'spacing', 'cutting']::text[], 'All five outside the three-point line, so the paint is empty for cutters. Pass, cut to the basket, then clear out to the open spot while everyone moves up one.', ARRAY['After you pass, cut to the basket. Every time.', 'The cutter clears out to the open spot; everyone else moves up one spot toward the ball.', 'With five out, the paint stays empty for cutters and drivers.', 'Show your hands as you cut: you are a target.', 'If your defender stops you cutting in front, cut behind them (back door).']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":48.5,"y":3},"o5":{"x":1.5,"y":3}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":48.5,"y":3},"o5":{"x":1.5,"y":3}},"ball":"o2","actions":[{"type":"pass","from":"o1","to":"o2","path":[]}]},{"ms":1000,"positions":{"o1":{"x":25,"y":7},"o2":{"x":45,"y":21},"o3":{"x":25,"y":31},"o4":{"x":48.5,"y":3},"o5":{"x":5,"y":21}},"ball":"o2","actions":[{"type":"cut","from":"o1","path":[]},{"type":"cut","from":"o3","path":[]},{"type":"cut","from":"o5","path":[]}],"note":"1 cuts; 3 and 5 each move up one spot."},{"ms":1000,"positions":{"o1":{"x":1.5,"y":3},"o2":{"x":45,"y":21},"o3":{"x":25,"y":31},"o4":{"x":48.5,"y":3},"o5":{"x":5,"y":21}},"ball":"o2","actions":[{"type":"cut","from":"o1","path":[{"x":14,"y":5}]}],"note":"1 clears out to the open corner."},{"ms":1000,"positions":{"o1":{"x":1.5,"y":3},"o2":{"x":45,"y":21},"o3":{"x":25,"y":31},"o4":{"x":48.5,"y":3},"o5":{"x":5,"y":21}},"ball":"o3","actions":[{"type":"pass","from":"o2","to":"o3","path":[]}]},{"ms":1000,"positions":{"o1":{"x":1.5,"y":3},"o2":{"x":25,"y":7},"o3":{"x":25,"y":31},"o4":{"x":45,"y":21},"o5":{"x":5,"y":21}},"ball":"o3","actions":[{"type":"cut","from":"o2","path":[]},{"type":"cut","from":"o4","path":[]}]},{"ms":1000,"positions":{"o1":{"x":1.5,"y":3},"o2":{"x":48.5,"y":3},"o3":{"x":25,"y":31},"o4":{"x":45,"y":21},"o5":{"x":5,"y":21}},"ball":"o3","actions":[{"type":"cut","from":"o2","path":[{"x":36,"y":5}]}]}]}'::jsonb, true),
  ('give-and-go', 'Give-and-go', 'principles', 'U9', ARRAY['cutting', 'passing', 'two-player']::text[], 'The oldest play in basketball: give the ball to a teammate, then go to the basket for the return pass.', ARRAY['Give (pass), then go (cut) straight away.', 'Take one step away first, then cut in front of your defender.', 'Cut with your hand up as a target.', '2: make the return pass early, before help arrives.', 'If your defender jumps toward the ball, cut behind them instead.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":15.5,"y":8}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":15.5,"y":8}},"ball":"o2","actions":[{"type":"pass","from":"o1","to":"o2","path":[]}],"note":"Give."},{"ms":1000,"positions":{"o1":{"x":21,"y":29},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":15.5,"y":8}},"ball":"o2","actions":[{"type":"cut","from":"o1","path":[]}],"note":"Step away to set your defender up."},{"ms":1000,"positions":{"o1":{"x":28,"y":8},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":15.5,"y":8}},"ball":"o2","actions":[{"type":"cut","from":"o1","path":[]}],"note":"Go: cut in front of your defender."},{"ms":1000,"positions":{"o1":{"x":28,"y":8},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":15.5,"y":8}},"ball":"o1","actions":[{"type":"pass","from":"o2","to":"o1","path":[]}],"note":"Return pass for the layup."}]}'::jsonb, true),
  ('back-door-high-post', 'Back door from the high post', 'principles', 'U10', ARRAY['cutting', 'back door', 'high post']::text[], 'When a defender stops the wing getting the ball, the wing cuts behind them. A pass to the high post is the signal.', ARRAY['If your defender is between you and the ball, cut behind them.', 'Walk your defender up the floor first, then plant your outside foot and go.', 'The pass to 5 at the high post is the signal to cut.', 'Use a bounce pass on a back-door cut, so it gets under the defender.', 'Keep the paint empty: 5 flashes up out of it.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":15.5,"y":8}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":25,"y":20}},"ball":"o1","actions":[{"type":"cut","from":"o5","path":[]}],"note":"5 flashes to the high post."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":43,"y":25},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":25,"y":20}},"ball":"o5","actions":[{"type":"pass","from":"o1","to":"o5","path":[]},{"type":"cut","from":"o2","path":[]}],"note":"2 takes the defender up the floor."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":29,"y":7},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":25,"y":20}},"ball":"o5","actions":[{"type":"cut","from":"o2","path":[{"x":38,"y":13}]}],"note":"2 plants and cuts back door."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":29,"y":7},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":25,"y":20}},"ball":"o2","actions":[{"type":"pass","from":"o5","to":"o2","path":[]}],"note":"Bounce pass."}]}'::jsonb, true),
  ('blob-box', 'Box: baseline out of bounds', 'blob', 'U10', ARRAY['out of bounds', 'box', 'screens']::text[], 'A set for the ball out of bounds under your own basket. Two players on the blocks, two at the elbows, and a screen to free a cutter at the rim.', ARRAY['Set up in a box: two on the blocks, two at the elbows. Your best passer takes it out.', 'The inbounder slaps the ball to start everyone at once.', '5 sets the screen with a wide base and holds still.', '4 waits for the screen, then cuts hard to the ball side of the basket with a hand up.', '3 pops to the corner and 2 goes out to the top as the safe pass.', 'After screening, 5 steps toward the basket. The screener is often the one left open.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":17,"y":19},"o3":{"x":33,"y":19},"o4":{"x":15.5,"y":8},"o5":{"x":34.5,"y":8}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":25,"y":31},"o3":{"x":33,"y":19},"o4":{"x":15.5,"y":8},"o5":{"x":21,"y":8}},"ball":"o1","actions":[{"type":"screen","from":"o5","to":"o4","path":[]},{"type":"cut","from":"o2","path":[]}],"note":"5 screens across for 4; 2 goes out as the safe pass."},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":25,"y":31},"o3":{"x":48.5,"y":3},"o4":{"x":30,"y":6},"o5":{"x":21,"y":8}},"ball":"o1","actions":[{"type":"cut","from":"o4","path":[{"x":21,"y":4}]},{"type":"cut","from":"o3","path":[]}],"note":"4 cuts under the screen to the ball side; 3 pops to the corner."},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":25,"y":31},"o3":{"x":48.5,"y":3},"o4":{"x":30,"y":6},"o5":{"x":22,"y":6.5}},"ball":"o1","actions":[{"type":"cut","from":"o5","path":[]}],"note":"5 seals and steps to the rim after screening."},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":25,"y":31},"o3":{"x":48.5,"y":3},"o4":{"x":30,"y":6},"o5":{"x":22,"y":6.5}},"ball":"o4","actions":[{"type":"pass","from":"o1","to":"o4","path":[]}],"note":"Inbound to 4 at the rim, or to 3 or 2 if 4 is covered."}]}'::jsonb, true),
  ('horns-high-low', 'Horns: ball screen and high-low', 'half_court', 'U12', ARRAY['horns', 'ball screen', 'high-low']::text[], 'Bigs at both elbows, shooters in both corners. One big screens for the guard and rolls; the other pops to the top and looks inside.', ARRAY['Set up wide: bigs at the elbows, shooters in the corners.', '5 sprints to screen and stops. 1 waits for the screen, then goes shoulder to shoulder past it.', '5 rolls to the basket with a hand up; 4 pops back to the top.', '1 reads it: pass to 5 if open; if 5 is covered, pass to 4 at the top.', '4 looks inside first: the high-low pass to 5.', 'Corners stay wide and ready to shoot.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":31},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":17,"y":19},"o5":{"x":33,"y":19}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":17,"y":19},"o5":{"x":28,"y":28.5}},"ball":"o1","actions":[{"type":"screen","from":"o5","to":"o1","path":[]}],"note":"5 screens for 1."},{"ms":1000,"positions":{"o1":{"x":38,"y":23},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":24,"y":30},"o5":{"x":27,"y":9}},"ball":"o1","actions":[{"type":"dribble","from":"o1","path":[{"x":31,"y":30.5}]},{"type":"cut","from":"o5","path":[]},{"type":"cut","from":"o4","path":[]}],"note":"1 uses the screen; 5 rolls, 4 pops to the top."},{"ms":1000,"positions":{"o1":{"x":38,"y":23},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":24,"y":30},"o5":{"x":27,"y":9}},"ball":"o4","actions":[{"type":"pass","from":"o1","to":"o4","path":[]}],"note":"5 is covered, so 1 passes to 4."},{"ms":1000,"positions":{"o1":{"x":38,"y":23},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":24,"y":30},"o5":{"x":27,"y":9}},"ball":"o5","actions":[{"type":"pass","from":"o4","to":"o5","path":[]}],"note":"High-low: 4 passes inside to 5."}]}'::jsonb, false),
  ('floppy', 'Floppy', 'half_court', 'U13', ARRAY['off-ball screens', 'shooter']::text[], 'The shooter starts under the basket with a screen on each side: one screener on the left, two on the right. Read your defender and come off the side that is open.', ARRAY['2 starts under the basket and picks the side that is open.', 'Walk your defender toward one side, then sprint off the screens to the other.', 'Screeners stand still, feet wide, arms in. No moving screens.', '2 catches ready to shoot: feet set, hands ready, facing the basket.', 'After the screen, a screener goes to the basket. The defence often forgets them.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":31},"o2":{"x":25,"y":6},"o3":{"x":15.5,"y":8},"o4":{"x":34.5,"y":8},"o5":{"x":34.5,"y":12}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":21,"y":6},"o3":{"x":15.5,"y":8},"o4":{"x":34.5,"y":8},"o5":{"x":34.5,"y":12}},"ball":"o1","actions":[{"type":"cut","from":"o2","path":[]}],"note":"2 walks the defender toward the single screen."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":15.5,"y":8},"o4":{"x":32.5,"y":9},"o5":{"x":32.5,"y":13}},"ball":"o1","actions":[{"type":"screen","from":"o4","to":"o2","path":[]},{"type":"screen","from":"o5","to":"o2","path":[]},{"type":"cut","from":"o2","path":[{"x":29,"y":10},{"x":30.5,"y":16.5}]}],"note":"4 and 5 screen; 2 sprints off them to the wing."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":15.5,"y":8},"o4":{"x":32.5,"y":9},"o5":{"x":32.5,"y":13}},"ball":"o2","actions":[{"type":"pass","from":"o1","to":"o2","path":[]}],"note":"Catch and shoot."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":32.5,"y":9},"o5":{"x":28,"y":8}},"ball":"o2","actions":[{"type":"cut","from":"o5","path":[]},{"type":"cut","from":"o3","path":[]}],"note":"5 goes to the basket; 3 lifts to the wing to keep the floor spaced."}]}'::jsonb, false),
  ('one-four-high', '1-4 high: back door, then high-low', 'half_court', 'U12', ARRAY['1-4 high', 'back door', 'high-low', 'high post']::text[], 'Four players across the free throw line extended, the guard at the top. The entry to the elbow starts two looks: the wing back door, then the other big diving in.', ARRAY['Line up flat: wings at the free throw line extended, bigs at the elbows.', 'The pass to 5 at the elbow starts the play.', 'First look: 2 cuts back door the moment 5 catches.', 'Not open? 2 keeps going out to the far corner, which pulls a defender away.', 'Second look: 4 dives to the basket for the high-low pass from 5.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":33},"o2":{"x":44,"y":23},"o3":{"x":6,"y":23},"o4":{"x":17,"y":19},"o5":{"x":33,"y":19}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":25,"y":33},"o2":{"x":44,"y":23},"o3":{"x":6,"y":23},"o4":{"x":17,"y":19},"o5":{"x":33,"y":19}},"ball":"o5","actions":[{"type":"pass","from":"o1","to":"o5","path":[]}],"note":"Entry pass to 5 at the elbow."},{"ms":1000,"positions":{"o1":{"x":25,"y":33},"o2":{"x":28,"y":7},"o3":{"x":6,"y":23},"o4":{"x":17,"y":19},"o5":{"x":33,"y":19}},"ball":"o5","actions":[{"type":"cut","from":"o2","path":[{"x":39,"y":13}]}],"note":"First look: 2 back door."},{"ms":1000,"positions":{"o1":{"x":25,"y":33},"o2":{"x":1.5,"y":3},"o3":{"x":6,"y":23},"o4":{"x":17,"y":19},"o5":{"x":33,"y":19}},"ball":"o5","actions":[{"type":"cut","from":"o2","path":[{"x":14,"y":4}]}],"note":"2 clears to the far corner."},{"ms":1000,"positions":{"o1":{"x":25,"y":33},"o2":{"x":1.5,"y":3},"o3":{"x":6,"y":23},"o4":{"x":23,"y":8},"o5":{"x":33,"y":19}},"ball":"o5","actions":[{"type":"cut","from":"o4","path":[]}],"note":"Second look: 4 dives to the basket."},{"ms":1000,"positions":{"o1":{"x":25,"y":33},"o2":{"x":1.5,"y":3},"o3":{"x":6,"y":23},"o4":{"x":23,"y":8},"o5":{"x":33,"y":19}},"ball":"o4","actions":[{"type":"pass","from":"o5","to":"o4","path":[]}],"note":"High-low pass."}]}'::jsonb, false),
  ('pick-and-roll-basic', 'Pick-and-roll: the basics', 'pick_and_roll', 'U12', ARRAY['ball screen', 'two-player']::text[], 'The big sets a screen for the ball handler, then rolls to the basket. The ball handler reads the big defender and makes the pass or the shot.', ARRAY['5: sprint to the screen and stop with a wide base before 1 moves.', '1: wait for the screen, then go shoulder to shoulder so your defender cannot slip through.', '5 rolls to the basket with a hand up as soon as 1 is past.', '1 reads 5''s defender: if they step up to you, pass to 5; if they stay back, shoot or keep driving.', 'Everyone else spaces out; 4 lifts to the top for the pass back out.', 'Ball screens are not allowed at U11 and under.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":31},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":5,"y":21},"o5":{"x":25,"y":20}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":5,"y":21},"o5":{"x":28,"y":28.5}},"ball":"o1","actions":[{"type":"screen","from":"o5","to":"o1","path":[]}],"note":"5 sprints up to screen."},{"ms":1000,"positions":{"o1":{"x":37,"y":22},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":5,"y":21},"o5":{"x":28,"y":28.5}},"ball":"o1","actions":[{"type":"dribble","from":"o1","path":[{"x":31.5,"y":30.5}]}],"note":"1 comes off the screen."},{"ms":1000,"positions":{"o1":{"x":37,"y":22},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":15.5,"y":28.5},"o5":{"x":27,"y":9}},"ball":"o1","actions":[{"type":"cut","from":"o5","path":[]},{"type":"cut","from":"o4","path":[]}],"note":"5 rolls to the basket; 4 lifts for the pass back out."},{"ms":1000,"positions":{"o1":{"x":37,"y":22},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":15.5,"y":28.5},"o5":{"x":27,"y":9}},"ball":"o5","actions":[{"type":"pass","from":"o1","to":"o5","path":[]}],"note":"Bounce pass to the roller."}]}'::jsonb, false),
  ('press-break-middle', 'Press break: hit the middle', 'press_break', 'U12', ARRAY['press break', 'full court']::text[], 'Beating a full-court press from your own baseline. Get it in, find the player flashing to the middle, and pass ahead. The hoop in the picture is the one you defend.', ARRAY['Get the ball in within 5 seconds: everyone is moving before the whistle.', 'Meet the pass. Never wait in a corner, where the press traps you.', 'The middle is the gap in most presses: 5 flashes to it, catches, turns and looks up the floor.', 'Pass first, dribble second. A pass beats the press faster than a dribble.', 'The inbounder steps in behind the ball as the safe pass back.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o4":{"x":30,"y":-2.5},"o1":{"x":18,"y":13},"o2":{"x":32,"y":13},"o5":{"x":25,"y":33},"o3":{"x":45,"y":42}},"ball":"o4","actions":[]},{"ms":1000,"positions":{"o4":{"x":30,"y":-2.5},"o1":{"x":8,"y":12},"o2":{"x":42,"y":10},"o5":{"x":25,"y":33},"o3":{"x":45,"y":42}},"ball":"o4","actions":[{"type":"cut","from":"o2","path":[]},{"type":"cut","from":"o1","path":[]}],"note":"1 and 2 cut hard to get open."},{"ms":1000,"positions":{"o4":{"x":30,"y":-2.5},"o1":{"x":8,"y":12},"o2":{"x":42,"y":10},"o5":{"x":25,"y":33},"o3":{"x":45,"y":42}},"ball":"o2","actions":[{"type":"pass","from":"o4","to":"o2","path":[]}],"note":"Inbound to 2."},{"ms":1000,"positions":{"o4":{"x":33,"y":3},"o1":{"x":7,"y":34},"o2":{"x":42,"y":10},"o5":{"x":25,"y":22},"o3":{"x":45,"y":42}},"ball":"o2","actions":[{"type":"cut","from":"o5","path":[]},{"type":"cut","from":"o4","path":[]},{"type":"cut","from":"o1","path":[]}],"note":"5 flashes to the middle; 4 steps in as the safe pass; 1 runs up the far side."},{"ms":1000,"positions":{"o4":{"x":33,"y":3},"o1":{"x":7,"y":34},"o2":{"x":42,"y":10},"o5":{"x":25,"y":22},"o3":{"x":45,"y":42}},"ball":"o5","actions":[{"type":"pass","from":"o2","to":"o5","path":[]}],"note":"Hit the middle."},{"ms":1000,"positions":{"o4":{"x":33,"y":3},"o1":{"x":7,"y":34},"o2":{"x":42,"y":10},"o5":{"x":25,"y":22},"o3":{"x":40,"y":49}},"ball":"o1","actions":[{"type":"pass","from":"o5","to":"o1","path":[]},{"type":"cut","from":"o3","path":[]}],"note":"5 turns and passes ahead; 3 runs on toward the other basket."},{"ms":1000,"positions":{"o4":{"x":33,"y":3},"o1":{"x":10,"y":48},"o2":{"x":42,"y":10},"o5":{"x":25,"y":22},"o3":{"x":40,"y":49}},"ball":"o1","actions":[{"type":"dribble","from":"o1","path":[]}],"note":"1 dribbles over half court."}]}'::jsonb, false)
